function run(input, params, h) {
  const low = s => String(s == null ? "" : s).trim().toLowerCase();
  const IS = low(params.is), AND = low(params.and), THE = low(params.the), SCENE = low(params.scene);
  const CHANGES = low(params.changes), FROM = low(params.from), TO = low(params.to), BECOMES = low(params.becomes);
  const listOf = s => String(s == null ? "" : s).split(",").map(w => low(w)).filter(w => w && w !== "-");
  const friendWords = listOf(params.friends), feelings = listOf(params.feelings);
  const wordsOf = text => {
    const out = [];
    let w = "";
    for (const c of String(text == null ? "" : text)) {
      h.tick();
      if (c.toLowerCase() !== c.toUpperCase() || (c >= "0" && c <= "9") || c === "'") {
        w += c;
      } else {
        if (w) out.push(w);
        w = "";
      }
    }
    if (w) out.push(w);
    return out;
  };
  const sentencesOf = line => {
    const out = [];
    let s = "";
    for (const c of String(line)) {
      h.tick();
      if (c === "." || c === "!" || c === "?" || c === ";") {
        if (s.trim()) out.push(s.trim());
        s = "";
      } else {
        s += c;
      }
    }
    if (s.trim()) out.push(s.trim());
    return out;
  };
  const joinAnd = list => (list.length < 2 ? list.join("") : list.slice(0, -1).join(", ") + " " + AND + " " + list[list.length - 1]);
  const count = (n, one, many) => n + " " + (n === 1 ? one : many);
  const readStory = text => {
    const m = { cast: [], called: {}, words: {}, relations: [], friends: [], scenes: [], unread: [], next: 0 };
    const names = new Map();
    const top = [], others = [];
    let scene = null;
    for (const raw of String(text == null ? "" : text).split("\n")) {
      h.tick();
      let line = raw.trim();
      const first = wordsOf(line);
      if (first.length && low(first[0]) === SCENE) {
        scene = { text: "", sentences: [] };
        m.scenes.push(scene);
        line = line.indexOf(":") >= 0 ? line.slice(line.indexOf(":") + 1) : first.slice(2).join(" ");
      }
      for (const s of sentencesOf(line)) {
        h.tick();
        if (scene) scene.sentences.push(s);
        else top.push(s);
      }
    }
    const rest = (lw, from) => lw.slice(from).filter(x => x !== AND && x !== THE);
    for (const s of top) {
      h.tick();
      const w = wordsOf(s), lw = w.map(low), k = lw.indexOf(IS);
      if (k < 1 || k > 3) {
        others.push(s);
        continue;
      }
      const the = k > 1 && lw[0] === THE;
      const name = w.slice(the ? 1 : 0, k).join(" ");
      if (!names.has(low(name))) {
        names.set(low(name), name);
        m.cast.push(name);
        m.words[name] = [];
        if (the) m.called[name] = THE + " " + name;
      }
      for (const word of rest(lw, k + 1)) {
        h.tick();
        if (m.words[names.get(low(name))].indexOf(word) < 0) m.words[names.get(low(name))].push(word);
      }
    }
    const findNames = lw => {
      const found = [];
      for (let i = 0; i < lw.length; i++) {
        h.tick();
        const two = lw[i] + " " + (lw[i + 1] || "");
        if (names.has(two)) {
          found.push({ name: names.get(two), at: i, end: i + 2 });
          i++;
        } else if (names.has(lw[i])) found.push({ name: names.get(lw[i]), at: i, end: i + 1 });
      }
      return found;
    };
    const readSentence = s => {
      const lw = wordsOf(s).map(low), who = findNames(lw);
      if (!who.length || who[0].at > 1) return null;
      if (lw[who[0].end] === IS) return { verb: IS, who: who[0].name, what: rest(lw, who[0].end + 1) };
      const c = lw.indexOf(CHANGES), f = lw.indexOf(FROM, c), t = lw.indexOf(TO, f);
      if (c === who[0].end && f > c && t > f) {
        const whom = who.find(x => x.at > c && x.at < f);
        return { verb: CHANGES, who: who[0].name, whom: whom ? whom.name : "", from: rest(lw.slice(0, t), f + 1), to: rest(lw, t + 1) };
      }
      if (lw[who[0].end] === BECOMES) {
        const what = rest(lw, who[0].end + 1);
        if (what.length && what.every(x => feelings.indexOf(x) >= 0)) return { verb: BECOMES, who: who[0].name, what: what };
        return { verb: CHANGES, who: who[0].name, whom: "", from: [], to: what };
      }
      if (who[0].end >= lw.length) return null;
      return { verb: lw[who[0].end], who: who[0].name, whom: who[1] ? who[1].name : "", also: who[2] ? who[2].name : "" };
    };
    for (const s of others) {
      h.tick();
      const r = readSentence(s);
      if (!r || !r.whom) {
        m.unread.push(s);
        continue;
      }
      m.relations.push({ who: r.who, verb: r.verb, whom: r.whom });
      if (friendWords.indexOf(r.verb) >= 0) m.friends.push([r.who, r.whom]);
    }
    m.scenes = m.scenes.map(sc => {
      const events = [], unread = [];
      for (const s of sc.sentences) {
        h.tick();
        const e = readSentence(s);
        if (e) events.push(e);
        else unread.push(s);
      }
      const on = m.cast.filter(n => events.some(e => e.who === n || e.whom === n || e.also === n));
      return { text: sc.sentences.join(". ") + ".", events: events, onStage: on, unread: unread };
    });
    return m;
  };
  const called = (m, n) => m.called[n] || n;
  const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
  const send = (m, note) => {
    if (m.next >= m.scenes.length) return { pass: false, over: true, say: (note ? note + " " : "") + "The end.", memory: m };
    const sc = m.scenes[m.next];
    const choose = m.next === 0 ? m.cast.map(n => ({ name: n, words: m.words[n].slice() })) : [];
    const changed = new Map();
    for (const e of sc.events) {
      h.tick();
      if (e.verb !== CHANGES) continue;
      const who = e.whom || e.who;
      const words = (changed.get(who) || m.words[who]).filter(x => e.from.indexOf(x) < 0);
      for (const x of e.to) {
        h.tick();
        if (words.indexOf(x) < 0) words.push(x);
      }
      changed.set(who, words);
    }
    let say = (note ? note + "\n\n" : "") + "**Scene " + (m.next + 1) + " of " + m.scenes.length + ".** " + sc.text + "\n\nOn stage: " + joinAnd(sc.onStage.map(n => called(m, n))) + ".";
    if (m.next === 0) say += "\n\nI read the story: " + count(m.cast.length, "character", "characters") + ", " + count(m.relations.length, "way", "ways") + " they get on, and " + count(m.scenes.length, "scene", "scenes") + ". The experts suggest values for everyone now, for the whole film:\n" + m.cast.map(n => "- " + called(m, n) + ": " + m.words[n].join(", ")).join("\n");
    for (const who of Array.from(changed.keys())) {
      h.tick();
      choose.push({ name: who + " " + params.after, of: who, words: changed.get(who) });
      if (m.called[who]) m.called[who + " " + params.after] = m.called[who] + " " + params.after;
      say += "\n\n" + cap(called(m, who)) + " changes, so the experts suggest values for " + called(m, who + " " + params.after) + ": " + changed.get(who).join(", ") + ".";
      m.words[who] = changed.get(who);
    }
    const unread = (m.next === 0 ? m.unread : []).concat(sc.unread);
    if (unread.length) say += "\n\nI couldn't read: " + unread.map(s => "“" + s + "”").join(", ") + ".";
    const out = { scene: m.next + 1, of: m.scenes.length, title: sc.text, cast: m.cast, called: m.called, choose: choose, onStage: sc.onStage, relations: m.relations, friends: m.friends, events: sc.events, unread: unread, say: say, memory: m };
    m.next = m.next + 1;
    return out;
  };
  if (!input.memory) {
    const m = readStory(input.text);
    if (!m.cast.length) return { pass: false, understood: false, say: "I couldn't find anyone in the story. Say what each character is like first, like “Cinderella is shy and kind.”" };
    if (!m.scenes.length) return { pass: false, understood: false, say: "There are no scenes in the story. Start each scene on a new line, like “Scene 1: Cinderella meets the Prince.”" };
    return send(m, "");
  }
  const m = input.memory;
  const d = input.data || {};
  return send(m, d.pass === false ? "Scene " + m.next + "'s film didn't run (" + String(d.error || "no reason given") + "), so on to the next scene." : "");
}

