function run(input, params, h) {
  const word = v => String(v == null ? "" : v).trim();
  const things = text => String(text == null ? "" : text).split(",").map(t => t.trim()).filter(t => t && t !== "-");
  const taste = { energy: word(params.energy), flashiness: word(params.flashiness), variety: word(params.variety), obviousness: word(params.obviousness), complexity: word(params.complexity), focus: word(params.focus) };
  const moving = things(params.energyFor), more = things(params.flashFor);
  const choosing = ((input.data || {}).choose || []).length > 0;
  const suggestions = [];
  if (choosing && taste.energy && taste.energy !== "-") suggestions.push({ who: "*", word: "energy", kind: "taste", says: moving.map(t => taste.energy + " " + t).join(", ") });
  if (choosing && taste.flashiness && taste.flashiness !== "-") suggestions.push({ who: "*", word: "flashiness", kind: "taste", says: moving.concat(more).map(t => taste.flashiness + " " + t).join(", ") });
  const cast = (input.data || {}).cast || [], call = n => ((input.data || {}).called || {})[n] || n;
  const missing = cast.length && !cast.some(n => String(n).toLowerCase() === taste.focus.toLowerCase()) ? taste.focus : "";
  if (missing) taste.focus = String(cast[0]);
  let say = "The film's taste: energy " + taste.energy + ", flashiness " + taste.flashiness + ", variety " + taste.variety + ", obviousness " + taste.obviousness + ", complexity " + taste.complexity + ". Its focus is " + call(taste.focus) + (missing ? ", the first one the Cast names, because " + missing + " isn't in this story" : "") + ".";
  say += suggestions.length ? "\n\nFor everyone being chosen: " + suggestions.map(s => s.word + " suggests " + s.says).join("; ") + "." : "\n\nNobody is being chosen, so the taste has nothing to suggest.";
  return { taste: taste, count: suggestions.length, suggestions: suggestions, say: say };
}

agents.pseudocode:
wait for the scene and the experts' suggestions: up to {20} messages, or until nobody else has anything to say
the things it chooses, each low, medium or high, with the words for them and for comparing:
  {speed: slow/fast, slower/faster} · {liveliness: calm/lively, calmer/livelier}
  {curves: straight/curvy, straighter/curvier} · {jerkiness: steady/jerky, steadier/jerkier}
  {purpose: aimless/purposeful, more aimless/more purposeful}
  {friends: wary of friends/drawn to friends} · {strangers: wary of strangers/drawn to strangers}
  {size: small/big, smaller/bigger} · {shape: smooth/pointed, smoother/pointier}
  {detail: simple/fancy, simpler/fancier} · {brightness: dim/bright, dimmer/brighter}
  {warmth: cool/warm, cooler/warmer} · {height: lower down/higher up, below/above}
the levels are {low, medium, high}, so "medium speed" is the middle one; "{same} speed" means someone else's speed
a suggestion is a word with {a bit} (weaker), {very} (stronger) or {not} (rules it out) before it
a suggestion counts its strength (a bit 1, plain 2, very 3) times where it came from:
  the character's own word {3}, a word meaning the same {2}, the opposite of a word {1}, a comparison {4}, the film's taste {1}
  a line like “Cinderella: a bit slow, big” from an AI agent {2}, or from {You} {3}; only its first 4 suggestions count
choose values for everyone the Cast says is being chosen: the film's focus first, then in the Cast's order
for each thing about each one, add up the suggestions for each value
  a comparison like "bigger than X" waits for X's value, then rules out X's value and below
  if two choices wait for each other, the first goes without its comparison
  the film's variety adds a weak suggestion: low variety the value used most so far, high the least, medium the middle one
  a value is ruled out if what is against it is at least as strong as what is for it
  if one value is more than {2} times as strong as the next, it wins
  if not, low and high meet in the middle, unless the middle is ruled out; then the stronger wins, or the one said first
  if nobody suggested anything, it is medium; if everything is ruled out, a comparison keeps its own direction
a subtle film keeps only each one's {3} strongest differences from medium
remember the values; a stand-in gets the variety and comparisons its character had, and then its values become the character's
explain {Cinderella} in full first (or the first one chosen, if nobody in the story is called that), then say everyone's values and how the arguments were settled, and name each word no expert knew, once

