function run(input, params, h) {
  const IDS = ["speed", "liveliness", "curves", "jerkiness", "purpose", "friends", "strangers", "size", "shape", "detail", "brightness", "warmth", "height"];
  const LOOKS = ["size", "shape", "detail", "brightness", "warmth"];
  const low = s => String(s == null ? "" : s).trim().toLowerCase();
  const cap = s => s.charAt(0).toUpperCase() + s.slice(1);
  const joinAnd = list => (list.length < 2 ? list.join("") : list.slice(0, -1).join(", ") + " and " + list[list.length - 1]);
  const levels = String(params.levels).split(",").map(low);
  const vocab = new Map(), names = {}, words = {};
  for (const id of IDS) {
    h.tick();
    const text = String(params[id] == null ? "" : params[id]), at = text.indexOf(":");
    const parts = text.slice(at + 1).split(",").map(p => p.split("/").map(low));
    names[id] = at > 0 ? low(text.slice(0, at)) : id;
    words[id] = [(parts[0] || [])[0] || "", (parts[0] || [])[1] || "", (parts[1] || [])[0] || "", (parts[1] || [])[1] || ""];
    if (words[id][0]) vocab.set(words[id][0], { el: id, v: 1 });
    if (words[id][1]) vocab.set(words[id][1], { el: id, v: 3 });
    if (words[id][2]) vocab.set(words[id][2], { el: id, dir: -1 });
    if (words[id][3]) vocab.set(words[id][3], { el: id, dir: 1 });
    levels.forEach((l, i) => vocab.set(l + " " + names[id], { el: id, v: i + 1 }));
    vocab.set(low(params.same) + " " + names[id], { el: id, dir: 0 });
  }
  const valueWord = (id, v) => (v === 1 && words[id][0] ? words[id][0] : v === 3 && words[id][1] ? words[id][1] : (levels[v - 1] || "medium") + " " + names[id]);
  const ABIT = low(params.abit), VERY = low(params.very), NOT = low(params.not);
  const read = phrase => {
    let p = low(phrase), s = 2, not = false;
    if (ABIT && p.indexOf(ABIT + " ") === 0) {
      s = 1;
      p = p.slice(ABIT.length + 1).trim();
    } else if (VERY && p.indexOf(VERY + " ") === 0) {
      s = 3;
      p = p.slice(VERY.length + 1).trim();
    }
    if (NOT && p.indexOf(NOT + " ") === 0) {
      not = true;
      p = p.slice(NOT.length + 1).trim();
    }
    const hit = vocab.get(p);
    return hit ? { el: hit.el, v: hit.v, dir: hit.dir, s: s, not: not } : null;
  };
  const weights = { own: +params.own || 0, same: +params.alike || 0, opposite: +params.opposite || 0, comparison: +params.comparison || 0, taste: +params.taste || 0, ai: +params.ai || 0, you: +params.you || 0 };
  const memory = input.memory || {};
  for (const k of ["values", "nets", "counts", "without", "variety"]) {
    memory[k] = memory[k] || {};
  }
  memory.looksFrom = memory.looksFrom || [];
  let scene = null, taste = {};
  const raw = [], knew = {}, unknown = {}, voices = [];
  for (const m of input.messages || []) {
    h.tick();
    const d = m.data || {};
    if (Array.isArray(d.choose)) scene = d;
    if (d.taste) taste = d.taste;
    if (!d.choose && !d.taste && !d.suggestions && m.text) voices.push(m);
    for (const x of d.suggestions || []) {
      h.tick();
      raw.push({ by: m.from, x: x });
    }
    for (const who of Object.keys(d.knew || {})) {
      h.tick();
      knew[who] = (knew[who] || []).concat(d.knew[who]);
    }
    for (const who of Object.keys(d.unknown || {})) {
      h.tick();
      unknown[who] = (unknown[who] || []).concat(d.unknown[who]);
    }
  }
  if (!scene) return { count: 0, say: "I didn't get the scene from the Cast, so there is nothing to choose.", memory: memory };
  const call = n => (scene.called || {})[n] || n;
  const tasteLevel = {};
  for (const k of Object.keys(taste)) {
    h.tick();
    tasteLevel[k] = levels.indexOf(low(taste[k])) + 1;
  }
  const focus = low(taste.focus);
  const choose = (scene.choose || []).filter(c => low(c.of || c.name) === focus).concat((scene.choose || []).filter(c => low(c.of || c.name) !== focus));
  const beingChosen = new Set(choose.map(c => c.name));
  const sugs = new Map(), bad = [], looksFrom = [];
  let n = 0;
  const PERSON = low(params.person), unused = [];
  const isCalled = (name, t) => low(name) === t || low(call(name)) === t;
  for (const m of voices) {
    h.tick();
    for (const line of String(m.text).split("\n")) {
      h.tick();
      const at = line.indexOf(":"), t = h.words(line.slice(0, Math.max(at, 0))).join(" ");
      const c = at > 0 ? choose.find(x => isCalled(x.name, t)) || choose.find(x => x.of && isCalled(x.of, t)) : null;
      const says = c ? line.slice(at + 1).split("(")[0].split(".").join("").split(",").filter(x => x.trim()) : [];
      if (c) raw.push({ by: m.from, x: { who: c.name, word: m.from, kind: low(m.from) === PERSON ? "you" : "ai", says: says.slice(0, 4).join(",") } });
      for (const extra of c ? says.slice(4) : line.trim() ? [line.trim()] : []) {
        h.tick();
        unused.push("“" + extra.trim().slice(0, 50) + "” (" + m.from + ")");
      }
    }
  }
  for (const r of raw) {
    h.tick();
    const x = r.x;
    const targets = x.who === "*" ? choose.map(c => c.name) : [x.who];
    for (const phrase of String(x.says || "").split(",")) {
      h.tick();
      if (!phrase.trim()) continue;
      const p = read(phrase);
      if (!p || (p.dir !== undefined && !x.of)) {
        if (bad.indexOf("“" + phrase.trim() + "” (" + r.by + ")") < 0) bad.push("“" + phrase.trim() + "” (" + r.by + ")");
        continue;
      }
      const kind = p.dir !== undefined ? "comparison" : x.kind;
      const turn = !!x.turn;
      const v = p.v === undefined ? undefined : turn ? 4 - p.v : p.v, dir = p.dir === undefined ? undefined : turn ? -p.dir : p.dir;
      const said = p.dir !== undefined ? (dir === 0 ? low(params.same) + " " + names[p.el] + " as " : words[p.el][dir > 0 ? 3 : 2] + " than ") + call(x.of) + " (" + x.word + ")"
        : kind === "taste" ? "the film's " + x.word
        : x.word + (x.from ? " (" + x.from + " brings it)" : "") + (kind === "same" ? " (like " + x.like + ")" : "") + (kind === "opposite" ? " (the opposite of " + x.like + ")" : "");
      for (const who of targets) {
        h.tick();
        if (!beingChosen.has(who)) continue;
        const key = who + "/" + p.el;
        if (!sugs.has(key)) sugs.set(key, []);
        sugs.get(key).push({ n: n++, v: v, dir: dir, of: x.of, not: p.not, w: p.s * (weights[kind] || 0), src: p.not ? "“" + NOT + " " + valueWord(p.el, v) + "” (" + said + ")" : said });
        if (LOOKS.indexOf(p.el) >= 0 && kind !== "taste" && kind !== "comparison" && looksFrom.indexOf(r.by) < 0) looksFrom.push(r.by);
      }
    }
  }
  const frozen = Object.keys(memory.values || {}).length > 0;
  const counts = {}, chosen = {}, nets = {}, why = {};
  for (const id of IDS) {
    h.tick();
    counts[id] = ((memory.counts || {})[id] || [0, 0, 0]).slice();
  }
  const valueFor = (who, el) => (chosen[who] && chosen[who][el] !== undefined ? chosen[who][el] : beingChosen.has(who) ? undefined : ((memory.values || {})[who] || {})[el]);
  const ofName = {};
  for (const c of choose) {
    h.tick();
    ofName[c.name] = c.of || c.name;
  }
  const stillWithout = (who, el) => frozen && ((memory.without || {})[ofName[who]] || []).indexOf(el) >= 0;
  const variety = el => {
    const c = counts[el], lv = tasteLevel.variety || 0;
    const most = [1, 2, 3].sort((a, b) => c[b - 1] - c[a - 1]), least = [1, 2, 3].sort((a, b) => c[a - 1] - c[b - 1]);
    return lv === 1 ? most[0] : lv === 3 ? least[0] : lv === 2 ? most[1] : 0;
  };
  const tally = { more: 0, middle: 0, stronger: 0, first: 0, alone: 0, nobody: 0, self: 0, waited: 0, without: 0 };
  const ratio = +params.ratio || 2;
  for (const c of choose) {
    chosen[c.name] = {};
    nets[c.name] = {};
    why[c.name] = {};
  }
  for (const el of IDS) {
    h.tick();
    const left = choose.map(c => c.name);
    while (left.length) {
      h.tick();
      const waits = who => (sugs.get(who + "/" + el) || []).filter(s => s.dir !== undefined && valueFor(s.of, el) === undefined && beingChosen.has(s.of));
      let k = left.findIndex(who => waits(who).length === 0);
      const embrace = k < 0;
      if (embrace) k = 0;
      const who = left.splice(k, 1)[0];
      const pro = [0, 0, 0], con = [0, 0, 0], first = [1e9, 1e9, 1e9], forV = [[], [], []], against = [[], [], []], without = [];
      let pull = 0;
      for (const s of sugs.get(who + "/" + el) || []) {
        h.tick();
        if (s.dir !== undefined) {
          const x = valueFor(s.of, el);
          if (x === undefined || stillWithout(who, el)) {
            without.push(s.src);
            continue;
          }
          if (beingChosen.has(s.of)) tally.waited++;
          if (s.dir === 0) {
            pro[x - 1] += s.w;
            forV[x - 1].push(s.src);
            first[x - 1] = Math.min(first[x - 1], s.n);
            continue;
          }
          pull += s.dir * s.w;
          for (let v = 1; v <= 3; v++) {
            if (s.dir > 0 ? v <= x : v >= x) {
              con[v - 1] += s.w;
              against[v - 1].push("“" + s.src.split(" (")[0] + "” (" + s.src.split(" (").slice(1).join(" ("));
            }
          }
          continue;
        }
        if (s.not) {
          con[s.v - 1] += s.w;
          against[s.v - 1].push(s.src);
          continue;
        }
        pro[s.v - 1] += s.w;
        forV[s.v - 1].push(s.src);
        first[s.v - 1] = Math.min(first[s.v - 1], s.n);
      }
      if (without.length) tally.without++;
      const vv = frozen && ((memory.variety || {})[ofName[who]] || {})[el] !== undefined ? memory.variety[ofName[who]][el] : variety(el);
      if (!frozen) {
        memory.variety[who] = memory.variety[who] || {};
        memory.variety[who][el] = vv;
      }
      if (vv && weights.taste) {
        pro[vv - 1] += weights.taste;
        forV[vv - 1].push("the film's variety");
        first[vv - 1] = Math.min(first[vv - 1], n + 1);
      }
      const net = [0, 1, 2].map(i => pro[i] - con[i]);
      const out = [0, 1, 2].map(i => con[i] > 0 && con[i] >= pro[i]);
      const standing = [1, 2, 3].filter(v => !out[v - 1]);
      const backed = standing.filter(v => pro[v - 1] > 0).sort((a, b) => net[b - 1] - net[a - 1] || first[a - 1] - first[b - 1]);
      let v = 2, how = "";
      if (!standing.length) {
        v = pull > 0 ? 3 : pull < 0 ? 1 : [1, 2, 3].sort((a, b) => net[b - 1] - net[a - 1])[0];
        how = pull ? "everything was ruled out, so the comparison kept its own direction" : "everything was ruled out, so the least ruled out won";
        tally.self++;
      } else if (!backed.length) {
        v = standing.indexOf(2) >= 0 ? 2 : standing[0];
        how = "nobody suggested anything that wasn't ruled out";
        tally.nobody++;
      } else if (backed.length === 1) {
        v = backed[0];
        how = [1, 2, 3].some(x => x !== v && pro[x - 1] > 0) ? "everything else was ruled out" : "nobody suggested anything else";
        tally.alone++;
      } else if (net[backed[0] - 1] > ratio * net[backed[1] - 1]) {
        v = backed[0];
        how = "more than " + ratio + " times as strong";
        tally.more++;
      } else if (backed[0] + backed[1] === 4 && !out[1]) {
        v = 2;
        how = valueWord(el, 1) + " and " + valueWord(el, 3) + " met in the middle";
        tally.middle++;
      } else {
        v = backed[0];
        how = net[backed[0] - 1] > net[backed[1] - 1] ? "stronger" : "said first";
        tally[net[backed[0] - 1] > net[backed[1] - 1] ? "stronger" : "first"]++;
      }
      chosen[who][el] = v;
      nets[who][el] = net;
      if (!frozen) counts[el][v - 1]++;
      why[who][el] = { value: valueWord(el, v), how: how, because: forV[v - 1], against: against[v - 1] };
      if (without.length) why[who][el].without = without;
      if (embrace && without.length) why[who][el].embrace = true;
    }
  }
  if (tasteLevel.obviousness === 1) {
    for (const c of choose) {
      h.tick();
      const ranked = IDS.filter(el => chosen[c.name][el] !== 2).sort((a, b) => Math.max(nets[c.name][b][0], nets[c.name][b][1], nets[c.name][b][2]) - Math.max(nets[c.name][a][0], nets[c.name][a][1], nets[c.name][a][2]));
      for (const el of ranked.slice(+params.subtle || 0)) {
        h.tick();
        chosen[c.name][el] = 2;
        why[c.name][el].value = valueWord(el, 2);
        why[c.name][el].how = "a subtle film keeps only " + (+params.subtle || 0) + " differences";
      }
    }
  }
  const before = {}, beforeNets = {};
  for (const name of (scene.onStage || []).concat(choose.map(c => c.of || c.name))) {
    before[name] = (memory.values || {})[name];
    beforeNets[name] = (memory.nets || {})[name];
  }
  const changed = [];
  for (const c of choose) {
    h.tick();
    const old = (memory.values || {})[c.of || ""];
    if (c.of && old) changed.push(call(c.of) + ": " + IDS.filter(el => old[el] !== chosen[c.name][el]).map(el => valueWord(el, old[el]) + " → " + valueWord(el, chosen[c.name][el])).join(", "));
    memory.values[c.of || c.name] = chosen[c.name];
    memory.nets[c.of || c.name] = { shape: nets[c.name].shape, detail: nets[c.name].detail };
    if (!frozen) memory.without[c.of || c.name] = IDS.filter(el => why[c.name][el].without);
  }
  memory.counts = counts;
  memory.looksFrom = memory.looksFrom.concat(looksFrom.filter(x => memory.looksFrom.indexOf(x) < 0));
  const choices = {}, strengths = {}, summary = {};
  const describe = vals => {
    const shown = IDS.filter(el => vals[el] !== 2).map(el => valueWord(el, vals[el])), mid = IDS.filter(el => vals[el] === 2).map(el => names[el]);
    return (shown.join(", ") || levels[1] + " in everything") + (shown.length && mid.length ? " (" + levels[1] + ": " + mid.join(", ") + ")" : "");
  };
  for (const name of (scene.onStage || []).concat(choose.filter(c => c.of).map(c => c.name))) {
    h.tick();
    const vals = beingChosen.has(name) ? chosen[name] : before[name];
    if (!vals) continue;
    choices[name] = vals;
    strengths[name] = beingChosen.has(name) ? { shape: nets[name].shape, detail: nets[name].detail } : beforeNets[name];
    summary[name] = describe(vals);
  }
  const lost = [], told = memory.told || [];
  for (const who of Object.keys(unknown)) {
    h.tick();
    for (const w of unknown[who]) {
      h.tick();
      if (lost.indexOf(w + " (" + call(who) + ")") < 0 && told.indexOf(w + " (" + call(who) + ")") < 0 && (knew[who] || []).indexOf(w) < 0) lost.push(w + " (" + call(who) + ")");
    }
  }
  memory.told = told.concat(lost);
  let everyone = "", say = "**Scene " + scene.scene + " of " + scene.of + ".** ";
  if (!choose.length) everyone = "Nobody's words changed, so everyone keeps the values chosen before:\n" + Object.keys(summary).map(nm => "- **" + call(nm) + "**: " + summary[nm]).join("\n");
  else everyone = (frozen ? "Someone's words changed, so I chose again for " + joinAnd(choose.map(c => call(c.name))) + ", with the variety and comparisons the first choosing gave them:\n" : "I chose everyone's values once, for the whole film" + (choose.some(c => low(c.name) === focus) ? ", " + call(choose[0].name) + " first, as the film's focus" : "") + ":\n") + choose.map(c => "- **" + call(c.name) + "**: " + describe(chosen[c.name])).join("\n");
  if (changed.length) everyone += "\n\nWhat changed: " + changed.join("; ") + ".";
  const named = choose.filter(c => low(c.of || c.name) === low(params.explain)).pop();
  const target = named || ((scene.cast || []).some(n => low(n) === low(params.explain)) ? null : choose[0]);
  const instead = target && !named && !frozen ? " " + params.explain + " isn't in this story, so I explain " + call(target.name) + ", the first one chosen." : "";
  const explained = [], FILM = "the film's ", STRONG = "more than " + ratio + " times as strong";
  let went = "", medium = "";
  if (target) {
    const w = why[target.name], gone = [], mid = [];
    IDS.forEach((el, i) => {
      if (w[el].without) gone.push(names[el]);
      if (chosen[target.name][el] === 2) {
        mid.push(names[el] + " (" + w[el].how + ")");
        return;
      }
      const film = w[el].because.filter(x => x.indexOf(FILM) === 0).map(x => x.slice(FILM.length)), own = w[el].because.filter(x => x.indexOf(FILM) !== 0);
      const p = Math.max(nets[target.name][el][0], nets[target.name][el][1], nets[target.name][el][2]);
      explained.push({ i: i, p: p, text: w[el].value + " because of " + joinAnd(own.concat(film.length ? [FILM + joinAnd(film)] : [])) + (w[el].against.length ? ", against " + joinAnd(w[el].against) : "") + (w[el].how === STRONG ? "" : " (" + w[el].how + ")") });
    });
    if (mid.length) medium = " " + cap(levels[1]) + ": " + mid.join("; ") + ".";
    if (gone.length) went = " " + (frozen ? "As in the first choosing, " + joinAnd(gone) : cap(call(target.name)) + " was chosen first, so " + joinAnd(gone)) + " went without a comparison.";
  }
  const parts = [[tally.more, STRONG], [tally.middle, "met in the middle"], [tally.stronger, "stronger"], [tally.first, "said first"], [tally.alone, "unopposed"], [tally.nobody, "nothing suggested"], [tally.self, "kept a comparison's own direction"]].filter(x => x[0] > 0);
  const settled = "**Settled:** " + parts.map(x => x[0] + " " + x[1]).join(", ") + ". " + tally.waited + (tally.waited === 1 ? " comparison" : " comparisons") + " waited for another's value" + (tally.without ? "; " + tally.without + " went without, because two choices waited for each other (Ani's “deadly embrace”)" : "") + ".";
  const tail = (lost.length ? "\n\n**Words no expert knew:** " + lost.join(", ") + "." : "") + (bad.length ? "\n\n**I couldn't read:** " + bad.join(", ") + "." : "") +
    (unused.length ? "\n\n**Not used** (only lines about someone being chosen now count, and only their first 4 suggestions): " + unused.slice(0, 6).join(", ") + (unused.length > 6 ? " …" : "") + "." : "");
