  let kept = explained.slice();
  if ((say + whyText(kept) + "\n\n" + everyone + "\n\n" + settled + tail).length > 1960) medium = "";
  while (kept.length && (say + whyText(kept) + "\n\n" + everyone + "\n\n" + settled + tail).length > 1960) {
    h.tick();
    kept = kept.sort((a, b) => b.p - a.p).slice(0, -1);
  }
