  }
  const segs = [];
  const side = (a, b) => (pos[a.id].x <= pos[b.id].x ? 1 : -1);
  const clampX = x => Math.max(-225, Math.min(225, x));
  const frames = (dist, speed) => Math.max(3, Math.min(24, Math.round(dist / Math.max(1, speed))));
  const line = (f, x1, y1) => ({ x0: pos[f.id].x, y0: pos[f.id].y, x1: clampX(x1), y1: y1 });
  const dist = (f, x1, y1) => Math.sqrt((pos[f.id].x - x1) * (pos[f.id].x - x1) + (pos[f.id].y - y1) * (pos[f.id].y - y1));
  const seg = (step, n, moves, extra) => {
    const from = {};
    for (const f of figures) {
      h.tick();
      if (pos[f.id]) from[f.id] = { x0: pos[f.id].x, y0: pos[f.id].y, x1: pos[f.id].x, y1: pos[f.id].y };
    }
    for (const id of Object.keys(moves)) {
      h.tick();
      const mv = moves[id];
      if (mv.x1 === undefined) continue;
      from[id] = mv;
      pos[id] = { x: mv.x1, y: mv.y1 };
    }
    const s = { step: step, n: n, moves: moves, from: from, makes: "", before: [], after: [] };
    for (const k of Object.keys(extra || {})) {
      h.tick();
      s[k] = extra[k];
    }
    segs.push(s);
    return s;
  };
  const lowLevel = (d.tasteLevel || {}).complexity === 1;
  (d.plan || []).forEach((p, i) => {
    const a = current[p.who], b = current[p.whom], c = current[p.third], m = {}, m2 = {};
    if (!a) return;
    if (p.way === "feels") {
      const ch = p.changes || {}, v = {};
      for (const el of Object.keys(a.v)) {
        h.tick();
        v[el] = a.v[el];
      }
      for (const el of Object.keys(ch)) {
        h.tick();
        v[el] = level(v, el, ch[el]) + 1;
      }
      a.v = v;
      a.speed = speeds[level(v, "speed")];
      const makes = "MAKE \"S" + a.id + " " + spins[level(v, "liveliness")] + " MAKE \"W" + a.id + " " + waves[level(v, "curves")] + " MAKE \"J" + a.id + " " + jolts[level(v, "jerkiness")] + (ken || !ch.brightness ? "" : " MAKE \"C" + a.id + " " + color(a.hue, lights[level(v, "brightness")]));
      if (!lowLevel && segs.length) {
        const first = segs.find(s => s.step === segs[segs.length - 1].step);
        first.makes += (first.makes ? " " : "") + makes;
        first.also = (first.also || []).concat([i]);
