  const num = v => String(r1(v));
  const lin = (a, b, n) => (r1(a) === r1(b) ? num(a) : num(a) + (b >= a ? " + " : " - ") + num(Math.abs(b - a) / n) + " * :T");
  const wait = Math.max(1, Math.round(60 / Math.max(1, +params.perSecond || 4)));
  const write = (comments, names, keep) => {
    let logo = comments ? "; Scene " + d.scene + " of " + d.of + ": " + d.title + "\n; Each TO draws one character: :T counts the frames, and :F is its size (1 is normal).\n" : "";
    logo += "SETLABELHEIGHT 11\n";
    if (screen) logo += "TO SCREEN\nSETPC \"black SETPENSIZE 100 REPEAT 4 [PU SETXY -256 96 * REPCOUNT - 240 PD SETXY 256 96 * REPCOUNT - 240] SETPENSIZE 3\nEND\n";
    logo += "TO SHAPE :X :Y :R :K :N :A :D\nMAKE \"S 2 * :R * SIN (:A / 2)\nREPEAT :D [PU SETXY :X + :R * SIN :K :Y + :R * COS :K SETH :K + 90 + :A / 2 PD REPEAT :N [FD :S RT :A] MAKE \"R :R * 0.7 MAKE \"S :S * 0.7]\nEND\n";
    if (figures.some(f => f.kind === "flower")) logo += "TO FLOWER :X :Y :R :K :D\nREPEAT 6 [SHAPE :X + :R / 2 * SIN (:K + 60 * REPCOUNT) :Y + :R / 2 * COS (:K + 60 * REPCOUNT) :R / 2 :K 6 60 1] SHAPE :X :Y :R / 3 :K 6 60 :D\nEND\n";
    for (const f of figures) {
      h.tick();
      const at = ":X + :J" + f.id + " * REMAINDER :T 2 :Y " + f.r + " * :F :S" + f.id + " * :T ";
      logo += "TO " + f.proc + " :X :Y :T :F\n" + (comments ? "; " + f.name + ": " + f.looks + "\n" : "") + "MAKE \"Y :Y + :W" + f.id + " * SIN (40 * :T)\nSETPC :C" + f.id + " " + (f.kind === "flower" ? "FLOWER " + at + f.outlines : "SHAPE " + at + SHAPES[f.kind].join(" ") + " " + f.outlines) + "\n" +
        (names && params.names !== false ? "PU SETXY :X - " + 3 * f.of.length + " :Y - " + (f.r + 18) + " SETPC \"" + (screen ? "silver" : "gray") + " LABEL [" + f.of + "]\n" : "") + "END\n";
    }
    logo += figures.map(f => "MAKE \"C" + f.id + " " + f.color + " MAKE \"W" + f.id + " " + f.wave + " MAKE \"J" + f.id + " " + f.jolt + " MAKE \"S" + f.id + " " + f.spin).join("\n") + "\n";
    const shown = new Map(onStage.map(n => [n, figures.find(f => f.name === n)]));
    let at = 0;
    for (const s of segs.slice(0, keep)) {
      h.tick();
      for (const sw of s.before) {
        h.tick();
        shown.set(sw[0], sw[1]);
      }
      const step = (d.plan || [])[s.step] || {};
      if (comments) logo += "; frames " + (at + 1) + "-" + (at + s.n) + ": " + step.says + (s.also ? "; " + s.also.map(j => (d.plan[j] || {}).says).join("; ") : "") + "\n";
      if (s.makes) logo += s.makes + "\n";
