        const f = shown.get(n), mv = s.moves[f.id] || {}, p = s.from[f.id] || { x0: 0, y0: 0, x1: 0, y1: 0 };
        const x = lin(p.x0, p.x1, s.n), y = lin(p.y0, p.y1, s.n);
