          shown.set(n, g);
        } else if (mv.orbit) body += " " + f.proc + " " + num(p.x0) + " + 40 * SIN (" + r1(360 * f.turns / s.n) + " * :T) " + num(p.y0) + " + 25 * SIN (" + r1(720 * f.turns / s.n) + " * :T) " + t + " 1";
        else if (mv.tryX !== undefined) body += " " + f.proc + " " + num(p.x0) + " + " + num(mv.tryX) + " * SIN (" + r1(180 / s.n) + " * :T) " + num(p.y0) + " " + t + " 1";
        else body += " " + f.proc + " " + x + " " + y + " " + t + (mv.pulse ? " 1 + 0.3 * (2 - :T)" : " 1");
