  if (keep < segs.length) left.push("the last " + (segs.length - keep) + " parts of the plan");
  const steps = [];
  let at = 0;
  for (const s of segs.slice(0, keep)) {
    h.tick();
    const what = ((d.plan || [])[s.step] || {}).says + (s.also ? "; " + s.also.map(j => (d.plan[j] || {}).says).join("; ") : "");
