  say += ken ? "\n\nNo expert said anything about looks, so they look as Ken drew them in 1978, in the Cast's order: " + figures.filter(f => f.name === f.of).map(f => call(f.name) + " a " + f.looks).join(", ") + "."
    : "\n\n**How they look:** " + figures.map(f => call(f.name) + ": " + f.looks + (f.outlines > 1 ? " (" + f.outlines + " outlines)" : "")).join("; ") + ".";
  if (notes.length) say += "\n\n" + notes.join(" ");
  if (wanted > most) say += "\n\nThe plan needed " + wanted + " frames, so each part got fewer, to stay within " + most + ".";
  if (left.length) say += "\n\nThe program was too long, so I left out " + left.join(", ") + ".";
  return { program: logo, fits: logo.length <= 3900, frames: at, seconds: r1(at / perSecond), steps: steps.map(s => ({ from: s.from, to: s.to, what: s.what })), looks: looks, say: say, memory: memory };
}
